8	/// Proof that this run may prompt; only [`Prompts::detect`] makes one.
9	pub struct Prompts(());
10	
11	impl Prompts {
12	    /// Prompts need a person at the terminal (stdin, and stderr where they draw) and a text run: `--format json` is for
13	    /// scripts and never prompts.
14	    pub fn detect(format: OutputFormat) -> Option<Self> {
15	        (format == OutputFormat::Text && std::io::stdin().is_terminal() && std::io::stderr().is_terminal())
16	            .then_some(Self(()))
17	    }
18	
19	    #[cfg(test)]
20	    pub fn for_tests() -> Self {
21	        Self(())
22	    }
23	}
