25	/// Printed whenever a prompt run ends without writing.
26	pub const CANCELLED: &str = "Cancelled, nothing written.";
27	
28	/// Exit status for a prompt cancelled with Esc or Ctrl-C: 130, as shells report SIGINT.
29	pub const CANCELLED_EXIT: u8 = 130;
30	
31	/// Asks which of `names` to pick, as `git add -i` does: the list is printed once, numbered, with `marked` ones starred,
32	/// then one typed line answers. Nothing is redrawn, so no terminal size or resize can misdraw it. Enter keeps the marked
33	/// ones; an answer that names nothing listed is asked again with the reason.
34	pub(crate) fn pick_many(heading: &str, names: &[String], marked: &[bool]) -> Result<Vec<usize>, CliError> {
35	    print_list(heading, names, marked);
36	    let enter = if marked.contains(&true) {
37	        "Enter keeps the * ones"
38	    } else {
39	        "Enter picks none"
40	    };
41	    eprintln!("{enter}, or type numbers, ranges (1-3) or names; Esc cancels.");
42	    loop {
43	        let answer = read_answer()?;
44	        if answer.trim().is_empty() {
45	            return Ok((0..names.len())
46	                .filter(|&index| marked.get(index) == Some(&true))
47	                .collect());
48	        }
49	        match choices(&answer, names) {
50	            Ok(picked) => return Ok(picked),
51	            Err(reason) => eprintln!("{reason}"),
52	        }
53	    }
54	}
55	
56	/// Asks for exactly one of `names`, the way [`pick_many`] asks for several.
57	pub(crate) fn pick_one(heading: &str, names: &[String]) -> Result<usize, CliError> {
58	    print_list(heading, names, &[]);
59	    eprintln!("Type a number or a name; Esc cancels.");
60	    loop {
61	        match choices(&read_answer()?, names).as_deref() {
62	            Ok(&[one]) => return Ok(one),
63	            Ok(_) => eprintln!("pick exactly one"),
64	            Err(reason) => eprintln!("{reason}"),
65	        }
66	    }
67	}
68	
69	fn print_list(heading: &str, names: &[String], marked: &[bool]) {
70	    let width = names.len().to_string().len();
71	    let mut text = format!("{heading}\n");
72	    for (index, name) in names.iter().enumerate() {
73	        let mark = if marked.get(index) == Some(&true) { '*' } else { ' ' };
74	        // A control character in a manifest's name must not drive the terminal.
75	        text.push_str(&format!("  {:>width$} {mark} {}\n", index + 1, name.escape_debug()));
76	    }
77	    eprint!("{text}");
78	}
79	
80	/// One typed line; Esc, Ctrl-C or end of input cancels. A key that sends an escape sequence (an arrow) asks again.
81	fn read_answer() -> Result<String, CliError> {
82	    loop {
83	        eprint!("> ");
84	        match line::read()? {
85	            Typed::Line(answer) => return Ok(answer),
86	            Typed::Cancel => {
87	                eprintln!();
88	                return Err(CliError::Cancelled);
89	            }
90	            #[cfg(unix)]
91	            Typed::Key => eprintln!("\nonly typed text is read here; type the answer again"),
92	        }
93	    }
94	}
95	
96	/// The listed indices an answer names, in list order. A word is a number or range counted from 1 (`3`, `1-3`) or a
97	/// listed name; words are separated by spaces or commas.
98	fn choices(answer: &str, names: &[String]) -> Result<Vec<usize>, String> {
99	    let mut picked = std::collections::BTreeSet::new();
100	    for word in answer
101	        .split(|c: char| c == ',' || c.is_whitespace())
102	        .filter(|word| !word.is_empty())
103	    {
104	        let shown = word.escape_debug();
105	        let by_name = names.iter().position(|name| name == word);
106	        let indices = match (by_name, numbered(word, names.len())) {
107	            (Some(index), None) => index..=index,
108	            (None, Some(range)) => range?,
109	            (Some(index), Some(Ok(range))) if range == (index..=index) => range,
110	            (Some(_), Some(_)) => return Err(format!("`{shown}` is both a listed name and another entry's number")),
111	            (None, None) => return Err(format!("`{shown}` is not a number, a range or a listed name")),
112	        };
113	        picked.extend(indices);
114	    }
115	    Ok(picked.into_iter().collect())
116	}
117	
118	/// `n` or `a-b`, counted from 1, as indices; `None` when the word is shaped like neither.
119	fn numbered(word: &str, len: usize) -> Option<Result<std::ops::RangeInclusive<usize>, String>> {
120	    let (first, last) = word.split_once('-').unwrap_or((word, word));
121	    let digits = |text: &str| !text.is_empty() && text.bytes().all(|byte| byte.is_ascii_digit());
122	    if !digits(first) || !digits(last) {
123	        return None;
124	    }
125	    let listed = |text: &str| text.parse::<usize>().ok().filter(|number| (1..=len).contains(number));
126	    Some(match (listed(first), listed(last)) {
127	        (Some(low), Some(high)) if low <= high => Ok(low - 1..=high - 1),
128	        (Some(_), Some(_)) => Err(format!("`{word}` runs backwards; put the lower number first")),
129	        _ => Err(format!("`{word}` is not in the list (1-{len})")),
130	    })
131	}
132	
133	enum Typed {
134	    Line(String),
135	    Cancel,
136	    /// A key that sends an escape sequence, such as an arrow.
137	    #[cfg(unix)]
138	    Key,
139	}
