141	#[cfg(unix)]
142	mod line {
143	    use std::os::fd::{AsFd as _, BorrowedFd};
144	
145	    use rustix::termios::{self, LocalModes, OptionalActions, QueueSelector, SpecialCodeIndex, Termios};
146	
147	    use super::Typed;
148	
149	    const ESC: u8 = 0x1b;
150	    const CTRL_C: u8 = 0x03;
151	
152	    /// Gives the terminal back the settings it had before the line was read.
153	    struct Restore<'a>(BorrowedFd<'a>, Termios);
154	
155	    impl Drop for Restore<'_> {
156	        fn drop(&mut self) {
157	            // A terminal that refuses its own earlier settings leaves nothing better to do.
158	            termios::tcsetattr(self.0, OptionalActions::Now, &self.1).ok();
159	        }
160	    }
161	
162	    /// Reads one line in the terminal's line mode, so the terminal does the editing and echo. Esc and Ctrl-C end the
163	    /// line instead of being typed, and Ctrl-C raises no signal, so either can cancel cleanly.
164	    pub fn read() -> std::io::Result<Typed> {
165	        let stdin = std::io::stdin();
166	        let fd = stdin.as_fd();
167	        let saved = termios::tcgetattr(fd)?;
168	        let _restore = Restore(fd, saved.clone());
169	        let mut mode = saved;
170	        mode.local_modes -= LocalModes::ISIG;
171	        mode.special_codes[SpecialCodeIndex::VEOL] = ESC;
172	        mode.special_codes[SpecialCodeIndex::VEOL2] = CTRL_C;
173	        termios::tcsetattr(fd, OptionalActions::Now, &mode)?;
174	        let mut line = Vec::new();
175	        loop {
176	            let mut buf = [0; 256];
177	            let read = read_some(fd, &mut buf)?;
178	            if read == 0 {
179	                return Ok(Typed::Cancel);
180	            }
181	            line.extend_from_slice(&buf[..read]);
182	            match line.last() {
183	                Some(b'\n') => {
184	                    line.pop();
185	                    return Ok(Typed::Line(String::from_utf8_lossy(&line).into_owned()));
186	                }
187	                Some(&CTRL_C) => return Ok(Typed::Cancel),
188	                Some(&ESC) => {
189	                    return Ok(if key_follows(fd, mode)? {
190	                        Typed::Key
191	                    } else {
192	                        Typed::Cancel
193	                    })
194	                }
195	                _ => {}
196	            }
197	        }
198	    }
199	
200	    /// Whether more bytes follow an Esc within 100 ms, as the rest of an arrow's escape sequence does; they are
201	    /// discarded.
202	    fn key_follows(fd: BorrowedFd<'_>, mut mode: Termios) -> std::io::Result<bool> {
203	        mode.local_modes -= LocalModes::ICANON | LocalModes::ECHO;
204	        mode.special_codes[SpecialCodeIndex::VMIN] = 0;
205	        mode.special_codes[SpecialCodeIndex::VTIME] = 1;
206	        termios::tcsetattr(fd, OptionalActions::Now, &mode)?;
207	        let mut buf = [0; 64];
208	        let followed = read_some(fd, &mut buf)? > 0;
209	        termios::tcflush(fd, QueueSelector::IFlush)?;
210	        Ok(followed)
211	    }
212	
213	    fn read_some(fd: BorrowedFd<'_>, buf: &mut [u8]) -> std::io::Result<usize> {
214	        loop {
215	            match rustix::io::read(fd, &mut *buf) {
216	                Err(rustix::io::Errno::INTR) => continue,
217	                result => return Ok(result?),
218	            }
219	        }
220	    }
221	}
222	
223	#[cfg(not(unix))]
224	mod line {
225	    use super::Typed;
226	
227	    /// Reads one line as the console gives it; the console keeps its own Esc and Ctrl-C behaviour.
228	    pub fn read() -> std::io::Result<Typed> {
229	        let mut line = String::new();
230	        if std::io::stdin().read_line(&mut line)? == 0 {
231	            return Ok(Typed::Cancel);
232	        }
233	        Ok(Typed::Line(line.trim_end_matches(['\r', '\n']).to_owned()))
234	    }
235	}
