237	/// The editor named by `$VISUAL`, else `$EDITOR`.
238	pub struct Editor {
239	    variable: &'static str,
240	    command: String,
241	}
242	
243	/// Why the editor could not be used; its message is the warning to print.
244	#[derive(Debug, thiserror::Error)]
245	#[error("cannot use ${variable} (`{command}`): {reason}; asking for the summary here instead")]
246	pub struct EditorUnusable {
247	    variable: &'static str,
248	    command: String,
249	    reason: String,
250	}
251	
252	impl Editor {
253	    /// An empty or blank setting is unset.
254	    pub fn from_env() -> Option<Self> {
255	        ["VISUAL", "EDITOR"].into_iter().find_map(|variable| {
256	            let command = std::env::var(variable).ok()?;
257	            (!command.trim().is_empty()).then_some(Self { variable, command })
258	        })
259	    }
260	
261	    /// `VISUAL` or `EDITOR`, whichever named it.
262	    pub fn variable(&self) -> &'static str {
263	        self.variable
264	    }
265	
266	    /// Opens the editor on an empty file and returns what was saved. `None` when the editor exits non-zero (an abort,
267	    /// as `:cq` in Vim). The editor draws on stderr so stdout stays for the report.
268	    pub fn edit(self) -> Result<Option<String>, EditorUnusable> {
269	        self.try_edit().map_err(|reason| EditorUnusable {
270	            variable: self.variable,
271	            command: self.command,
272	            reason,
273	        })
274	    }
275	
276	    fn try_edit(&self) -> Result<Option<String>, String> {
277	        let words =
278	            shell_words::split(&self.command).map_err(|error| format!("it does not split into words: {error}"))?;
279	        let Some((program, args)) = words.split_first() else {
280	            return Err("it names no program".to_owned());
281	        };
282	        let failed = |error: std::io::Error| error.to_string();
283	        let file = tempfile::Builder::new()
284	            .prefix("callisto-")
285	            .suffix(".txt")
286	            .tempfile()
287	            .map_err(failed)?;
288	        let _editor_owns_ctrl_c = editor_owns_ctrl_c::enter().map_err(failed)?;
289	        let status = crate::runner::child_command(program, &[], &[])
290	            .args(args)
291	            .arg(file.path())
292	            .stdout(std::io::stderr())
293	            .status()
294	            .map_err(|error| format!("`{program}` did not start: {error}"))?;
295	        if !status.success() {
296	            return Ok(None);
297	        }
298	        let saved = std::fs::read(file.path()).map_err(failed)?;
299	        String::from_utf8(saved)
300	            .map(Some)
301	            .map_err(|error| format!("what it saved is not UTF-8 text: {}", error.utf8_error()))
302	    }
303	}
304	
305	#[cfg(unix)]
306	mod editor_owns_ctrl_c {
307	    use std::sync::atomic::{AtomicBool, Ordering};
308	    use std::sync::Arc;
309	
310	    use signal_hook::consts::SIGINT;
311	
312	    /// Ctrl-C in a line-mode editor reaches this process too: as Git's `launch_editor` does, ignore SIGINT while the
313	    /// editor runs and let its exit status decide. Dropping this gives SIGINT its default action back.
314	    pub struct Guard(Arc<AtomicBool>);
315	
316	    pub fn enter() -> std::io::Result<Guard> {
317	        let default_action = Arc::new(AtomicBool::new(false));
318	        signal_hook::flag::register_conditional_default(SIGINT, Arc::clone(&default_action))?;
319	        Ok(Guard(default_action))
320	    }
321	
322	    impl Drop for Guard {
323	        fn drop(&mut self) {
324	            self.0.store(true, Ordering::SeqCst);
325	        }
326	    }
327	}
328	
329	#[cfg(not(unix))]
330	mod editor_owns_ctrl_c {
331	    pub struct Guard;
332	
333	    pub fn enter() -> std::io::Result<Guard> {
334	        Ok(Guard)
335	    }
336	}
