339	mod tests {
340	    use super::choices;
341	
342	    fn names(names: &[&str]) -> Vec<String> {
343	        names.iter().map(|name| (*name).to_owned()).collect()
344	    }
345	
346	    #[test]
347	    fn an_answer_picks_by_number_range_and_name_in_list_order() {
348	        let listed = names(&["a", "b", "c", "d", "cargo/e"]);
349	        assert_eq!(choices("3, 1", &listed), Ok(vec![0, 2]));
350	        assert_eq!(choices("2-4", &listed), Ok(vec![1, 2, 3]));
351	        assert_eq!(choices("cargo/e a 1", &listed), Ok(vec![0, 4]));
352	        assert_eq!(choices("1-1,,  b", &listed), Ok(vec![0, 1]));
353	    }
354	
355	    #[test]
356	    fn an_answer_naming_nothing_listed_says_why() {
357	        let listed = names(&["a", "b", "c"]);
358	        for (answer, reason) in [
359	            ("0", "`0` is not in the list (1-3)"),
360	            ("4", "`4` is not in the list (1-3)"),
361	            ("2-9", "`2-9` is not in the list (1-3)"),
362	            ("99999999999999999999999", "is not in the list (1-3)"),
363	            ("3-1", "`3-1` runs backwards"),
364	            ("x", "`x` is not a number, a range or a listed name"),
365	            ("1-", "`1-` is not a number"),
366	            ("-1", "`-1` is not a number"),
367	            ("A", "`A` is not a number"),
368	        ] {
369	            let error = choices(answer, &listed).expect_err(answer);
370	            assert!(error.contains(reason), "{answer}: {error}");
371	        }
372	    }
373	
374	    #[test]
375	    fn a_name_that_reads_as_another_entrys_number_is_refused() {
376	        let ambiguous = "is both a listed name and another entry's number";
377	        assert!(choices("2", &names(&["2", "b"])).unwrap_err().contains(ambiguous));
378	        assert!(choices("1-2", &names(&["a", "b", "1-2"]))
379	            .unwrap_err()
380	            .contains(ambiguous));
381	        // A name that is its own number is not ambiguous.
382	        assert_eq!(choices("1", &names(&["1", "b"])), Ok(vec![0]));
383	    }
384	}
